// Detekterar röstkommandon och rensar text
const text = $input.item.json.transcription;

const voiceTriggers = [
  'skapa bild',
  'generera bild',
  'skapa en bild',
  'generera en bild',
  'gör en bild'
];

// Kolla om något röstkommando finns
const hasVoiceCommand = voiceTriggers.some(trigger => 
  text.toLowerCase().includes(trigger)
);

// Ta bort röstkommandon från texten
let cleanedText = text;
for (const trigger of voiceTriggers) {
  const regex = new RegExp(trigger, 'gi');
  cleanedText = cleanedText.replace(regex, '').trim();
}

// Kolla om mening är komplett (har skiljetecken)
const hasEndPunctuation = /[.!?:;]\s*$/.test(text);

console.log('🎯 Voice command detected:', hasVoiceCommand);
console.log('📏 Complete sentence:', hasEndPunctuation);
console.log('✨ Cleaned text:', cleanedText);

return {
  json: {
    original_text: text,
    cleaned_text: cleanedText,
    voice_command: hasVoiceCommand,
    complete_sentence: hasEndPunctuation,
    should_generate: hasVoiceCommand || hasEndPunctuation
  }
};

