// Extrahera den förbättrade prompten från Gemini-svaret
const response = $input.item.json;

let enhancedPrompt = '';

if (response.candidates && response.candidates[0]) {
  const candidate = response.candidates[0];
  if (candidate.content && candidate.content.parts) {
    enhancedPrompt = candidate.content.parts[0].text.trim();
  }
}

console.log('✨ Enhanced prompt:', enhancedPrompt);

return {
  json: {
    enhanced_prompt: enhancedPrompt,
    original_text: $('🎯 Röstkommando-detektion').item.json.original_text,
    cleaned_text: $('🎯 Röstkommando-detektion').item.json.cleaned_text
  }
};

// Extrahera bilden från Gemini-svaret och konvertera till binary för visning i n8n
const response = $input.item.json;

let imageBase64 = null;

// Försök hitta bilden i olika delar av responsen
if (response.candidates && response.candidates[0]) {
  const candidate = response.candidates[0];
  if (candidate.content && candidate.content.parts) {
    for (const part of candidate.content.parts) {
      if (part.inlineData && part.inlineData.data) {
        imageBase64 = part.inlineData.data;
        break;
      }
    }
  }
}

if (!imageBase64) {
  throw new Error('Ingen bild hittades i Gemini-svaret');
}

const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
const filename = `image_${timestamp}.png`;

console.log('🎨 Bild genererad!', filename);

// Konvertera base64 till Buffer för n8n binary display
const imageBuffer = Buffer.from(imageBase64, 'base64');

return {
  json: {
    success: true,
    filename: filename,
    enhanced_prompt: $('📤 Extrahera Prompt').item.json.enhanced_prompt,
    original_text: $('📤 Extrahera Prompt').item.json.original_text,
    timestamp: timestamp,
    size_bytes: imageBuffer.length
  },
  binary: {
    data: {
      data: imageBuffer.toString('base64'),
      mimeType: 'image/png',
      fileName: filename,
      fileExtension: 'png'
    }
  }
};
